mapper.select:
SELECT
    t2.short_name AS customer_short_name,
    t1.id, t1.customer_id, t1.change_amount, t1.balance_before, t1.balance_after,
    t1.biz_type, t1.ref_type, t1.ref_id, t1.ref_no, t1.remark,
    t1.create_time, t1.update_time, t1.creator, t1.updater
FROM zc_customer_balance_log t1
LEFT JOIN zc_customer t2 ON t1.customer_id = t2.id AND t2.deleted = 0
WHERE t1.deleted = 0

    AND t1.customer_id = #{reqVO.customerId}


    AND t1.biz_type = #{reqVO.bizType}


    AND t1.ref_type = #{reqVO.refType}


    AND t1.ref_id = #{reqVO.refId}


    AND t1.ref_no = #{reqVO.refNo}


    AND t1.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

ORDER BY t1.id DESC
